insert into public.competencia (id, trilha, topico_id, titulo, descricao, criterio, ordem) values
  ('py-comp-apl-01', 'python', 'py-apl-01', 'Importar código com clareza', 'Organiza código em módulos e importa apenas o que a tarefa precisa.', 'Cria um arquivo reutilizável e importa uma função sem depender de efeitos de execução acidentais.', 10),
  ('py-comp-apl-02', 'python', 'py-apl-02', 'Escolher recursos da biblioteca padrão', 'Consulta módulos nativos antes de adicionar dependências externas.', 'Identifica um módulo padrão adequado e explica quando uma dependência externa seria necessária.', 20),
  ('py-comp-apl-03', 'python', 'py-apl-03', 'Manipular datas e durações', 'Usa date, datetime e timedelta em vez de cálculos frágeis com texto.', 'Calcula e formata uma data com objetos apropriados e testa uma virada de mês.', 30),
  ('py-comp-apl-04', 'python', 'py-apl-04', 'Construir caminhos portáveis', 'Usa pathlib para compor caminhos sem fixar separadores de um sistema.', 'Localiza e compõe caminhos relativos ao projeto usando Path.', 40),
  ('py-comp-apl-05', 'python', 'py-apl-05', 'Ler e gravar arquivos com segurança', 'Usa context managers e escolhe o modo de abertura conscientemente.', 'Lê ou grava um arquivo com with e explica se o modo preserva ou substitui conteúdo.', 50),
  ('py-comp-apl-06', 'python', 'py-apl-06', 'Persistir dados em JSON', 'Serializa e lê estruturas compatíveis com JSON e valida dados carregados.', 'Salva e recupera uma estrutura simples sem assumir que todo arquivo é válido.', 60),
  ('py-comp-apl-07', 'python', 'py-apl-07', 'Processar CSV com cabeçalhos', 'Usa o módulo csv para respeitar campos entre aspas e nomes de colunas.', 'Lê um CSV por cabeçalho e acessa um campo pelo nome, inclusive quando o texto contém vírgula.', 70),
  ('py-comp-apl-08', 'python', 'py-apl-08', 'Tratar exceções específicas', 'Prevê falhas esperadas e captura somente o erro que sabe resolver.', 'Informa um próximo passo útil sem esconder exceções inesperadas.', 80),
  ('py-comp-apl-09', 'python', 'py-apl-09', 'Instalar dependências no ambiente correto', 'Usa pip e documentação para adicionar bibliotecas de maneira reproduzível.', 'Confirma o ambiente ativo, instala nele e registra dependências necessárias.', 90),
  ('py-comp-apl-10', 'python', 'py-apl-10', 'Consumir uma API com limites e validação', 'Faz uma requisição HTTP com timeout e verifica resposta e dados recebidos.', 'Trata falha de rede, status inesperado e campo ausente sem aguardar indefinidamente.', 100),
  ('py-comp-pro-01', 'python', 'py-pro-01', 'Registrar mudanças com Git', 'Usa o estado do repositório para selecionar e registrar alterações pequenas.', 'Revê git status e cria commits que representam uma mudança compreensível.', 10),
  ('py-comp-pro-02', 'python', 'py-pro-02', 'Publicar um repositório sem expor segredos', 'Sincroniza um repositório remoto e protege credenciais e dados privados.', 'Revisa os arquivos antes do push e mantém chaves fora do código e do histórico.', 20),
  ('py-comp-pro-03', 'python', 'py-pro-03', 'Trabalhar com branches e merges', 'Isola mudanças e resolve conflitos preservando a intenção das duas alterações.', 'Cria uma branch, integra mudanças e verifica o resultado do merge.', 30),
  ('py-comp-pro-04', 'python', 'py-pro-04', 'Isolar o ambiente Python', 'Cria e ativa um ambiente virtual próprio para o projeto.', 'Executa o projeto no ambiente local sem alterar o Python global do sistema.', 40),
  ('py-comp-pro-05', 'python', 'py-pro-05', 'Reproduzir dependências do projeto', 'Registra e instala dependências no ambiente de desenvolvimento.', 'Outra pessoa instala as dependências a partir das instruções do repositório.', 50),
  ('py-comp-pro-06', 'python', 'py-pro-06', 'Depurar com hipótese', 'Investiga um defeito observando o estado relevante do programa.', 'Formula uma hipótese, inspeciona valores e testa uma mudança por vez.', 60),
  ('py-comp-pro-07', 'python', 'py-pro-07', 'Interpretar tracebacks', 'Usa a última linha e o contexto do traceback para localizar a causa provável.', 'Encontra o tipo do erro e a linha relevante antes de propor uma correção.', 70),
  ('py-comp-pro-08', 'python', 'py-pro-08', 'Escrever testes automatizados', 'Descreve comportamentos esperados em testes reproduzíveis.', 'Cria testes com casos comuns e limites que falham quando a regra é quebrada.', 80),
  ('py-comp-pro-09', 'python', 'py-pro-09', 'Formatar e analisar código com Ruff', 'Usa formatação e lint para detectar problemas e manter estilo consistente.', 'Roda Ruff e corrige os avisos relevantes sem tratar a ferramenta como substituta da revisão.', 90),
  ('py-comp-pro-10', 'python', 'py-pro-10', 'Documentar um projeto reproduzível', 'Explica objetivo, instalação, uso, testes e limitações no README.', 'Uma pessoa que não participou do desenvolvimento consegue seguir as instruções.', 100),
  ('py-comp-projeto-despesas', 'python', 'py-apl-10', 'Gerenciar despesas com persistência JSON', 'Combina arquivos, dados estruturados, validação e funções em uma aplicação útil.', 'Outra pessoa cadastra, consulta e calcula saldo; os dados sobrevivem à próxima execução e entradas inválidas recebem orientação.', 110),
  ('py-comp-projeto-ferramentas', 'python', 'py-pro-10', 'Entregar um projeto Python reproduzível', 'Refatora um projeto anterior e o entrega com ambiente, testes, qualidade e documentação.', 'O projeto passa nos testes e nas verificações de estilo e pode ser instalado e executado seguindo o README.', 110)
insert into public.atividade (id, trilha, topico_id, tipo, titulo, enunciado, configuracao, dificuldade, ordem, publicada) values
  ('py-quiz-apl-01', 'python', 'py-apl-01', 'quiz', 'Importar sem executar o programa inteiro', 'Um arquivo calculos.py define a função somar e também contém um menu dentro de if __name__ == "__main__". O que acontece ao importar somar de calculos?', '{"multipla":false,"alternativas":[{"id":"a","texto":"A definição da função fica disponível; o bloco principal não roda durante a importação."},{"id":"b","texto":"Todo o arquivo deixa de ser lido."},{"id":"c","texto":"Python executa o menu principal automaticamente em qualquer importação."},{"id":"d","texto":"Importar uma função copia o arquivo para a pasta atual."}]}'::jsonb, 'iniciante', 10, true),
  ('py-completar-apl-01', 'python', 'py-apl-01', 'completar', 'Importe somente a função necessária', 'Complete a importação para usar somar definida em calculos.py.', '{"codigo":"from calculos ___ somar\nprint(somar(2, 3))","lacunas":[{"id":"palavra","rotulo":"Palavra que introduz o módulo"}]}'::jsonb, 'iniciante', 20, true),
  ('py-quiz-apl-02', 'python', 'py-apl-02', 'quiz', 'Procure antes de instalar', 'Você precisa calcular a raiz quadrada de um número. Qual é o primeiro passo mais apropriado?', '{"multipla":false,"alternativas":[{"id":"a","texto":"Verificar a documentação do módulo math da biblioteca padrão."},{"id":"b","texto":"Instalar um pacote aleatório sem ler sua documentação."},{"id":"c","texto":"Copiar uma biblioteca inteira para o projeto."},{"id":"d","texto":"Reescrever o interpretador Python."}]}'::jsonb, 'iniciante', 10, true),
  ('py-saida-apl-02', 'python', 'py-apl-02', 'saida', 'Uma função da biblioteca padrão', 'Qual valor é exibido pelo exemplo que arredonda para baixo?', '{"codigo":"import math\nprint(math.floor(4.9))","rotuloResposta":"Número exibido"}'::jsonb, 'iniciante', 20, true),
  ('py-quiz-apl-03', 'python', 'py-apl-03', 'quiz', 'Some dias a uma data', 'Qual recurso representa corretamente um intervalo de três dias que pode ser somado a uma data?', '{"multipla":false,"alternativas":[{"id":"a","texto":"timedelta(days=3)"},{"id":"b","texto":"date(3)"},{"id":"c","texto":"\"3 dias\""},{"id":"d","texto":"datetime.months(3)"}]}'::jsonb, 'iniciante', 10, true),
  ('py-saida-apl-03', 'python', 'py-apl-03', 'saida', 'Avance no calendário', 'A biblioteca calcula a virada do mês. Informe a data resultante.', '{"codigo":"from datetime import date, timedelta\ndata = date(2025, 1, 30)\nprint((data + timedelta(days=2)).isoformat())","rotuloResposta":"Data no formato AAAA-MM-DD"}'::jsonb, 'iniciante', 20, true),
  ('py-quiz-apl-04', 'python', 'py-apl-04', 'quiz', 'Monte caminhos em qualquer sistema', 'Qual expressão compõe uma pasta e um nome de arquivo usando pathlib?', '{"multipla":false,"alternativas":[{"id":"a","texto":"pasta / \"dados.json\""},{"id":"b","texto":"Montar manualmente a barra separadora dentro de uma string"},{"id":"c","texto":"Path(pasta, \"dados.json\") sem importar Path"},{"id":"d","texto":"pasta(\"dados.json\")"}]}'::jsonb, 'iniciante', 10, true),
  ('py-completar-apl-04', 'python', 'py-apl-04', 'completar', 'Componha o caminho do arquivo', 'Complete o operador de pathlib que junta um diretório e um arquivo.', '{"codigo":"from pathlib import Path\narquivo = Path(\"dados\") ___ \"alunos.json\"","lacunas":[{"id":"operador","rotulo":"Operador para compor caminhos"}]}'::jsonb, 'iniciante', 20, true),
  ('py-quiz-apl-05', 'python', 'py-apl-05', 'quiz', 'Escolha o modo sem apagar conteúdo', 'Você quer acrescentar uma linha a um arquivo existente. Qual modo evita apagar o texto anterior?', '{"multipla":false,"alternativas":[{"id":"a","texto":"\"a\""},{"id":"b","texto":"\"w\""},{"id":"c","texto":"\"x\""},{"id":"d","texto":"\"r\""}]}'::jsonb, 'iniciante', 10, true),
  ('py-erro-apl-05', 'python', 'py-apl-05', 'erro', 'Evite perder o conteúdo anterior', 'Uma rotina abriu relatorio.txt com open(arquivo, "w") só para acrescentar uma linha. Qual é o problema?', '{"multipla":false,"alternativas":[{"id":"a","texto":"O modo w substitui o conteúdo existente; para acrescentar, use a."},{"id":"b","texto":"O modo w só funciona em arquivos JSON."},{"id":"c","texto":"Todo arquivo deve ser aberto sem modo."},{"id":"d","texto":"O modo a apaga os dados antes de gravar."}]}'::jsonb, 'iniciante', 20, true),
  ('py-quiz-apl-06', 'python', 'py-apl-06', 'quiz', 'Ler ou gravar JSON', 'Qual par de funções lê um arquivo JSON e grava uma estrutura Python em um arquivo JSON?', '{"multipla":false,"alternativas":[{"id":"a","texto":"json.load e json.dump"},{"id":"b","texto":"json.read e json.write"},{"id":"c","texto":"json.open e json.close"},{"id":"d","texto":"json.parse e json.save"}]}'::jsonb, 'iniciante', 10, true),
  ('py-completar-apl-06', 'python', 'py-apl-06', 'completar', 'Carregue os dados JSON', 'O arquivo já foi aberto como arquivo_json. Complete a função que transforma o conteúdo em dados Python.', '{"codigo":"import json\nwith open(\"alunos.json\", encoding=\"utf-8\") as arquivo_json:\n    alunos = json.___(arquivo_json)","lacunas":[{"id":"funcao","rotulo":"Função que carrega JSON de um arquivo"}]}'::jsonb, 'iniciante', 20, true),
  ('py-quiz-apl-07', 'python', 'py-apl-07', 'quiz', 'Leia CSV com nomes de coluna', 'Uma coluna CSV pode conter "Silva, Ana". Por que csv.DictReader é mais seguro que dividir cada linha por vírgula?', '{"multipla":false,"alternativas":[{"id":"a","texto":"Ele respeita as regras de campos entre aspas e permite acessar valores pelo cabeçalho."},{"id":"b","texto":"Ele remove todas as colunas com vírgulas."},{"id":"c","texto":"Ele converte automaticamente cada campo em número."},{"id":"d","texto":"Ele lê apenas arquivos sem cabeçalho."}]}'::jsonb, 'iniciante', 10, true),
  ('py-completar-apl-07', 'python', 'py-apl-07', 'completar', 'Use o leitor por cabeçalho', 'Complete para criar um leitor que associa cada valor ao nome da coluna.', '{"codigo":"import csv\nleitor = csv.___(arquivo)","lacunas":[{"id":"leitor","rotulo":"Leitor CSV que usa cabeçalhos como chaves"}]}'::jsonb, 'iniciante', 20, true),
  ('py-quiz-apl-08', 'python', 'py-apl-08', 'quiz', 'Capture a falha que você prevê', 'Uma função abre um arquivo que pode não existir. Qual estratégia informa a pessoa sem esconder outros defeitos inesperados?', '{"multipla":false,"alternativas":[{"id":"a","texto":"Capturar FileNotFoundError e orientar a conferir o caminho."},{"id":"b","texto":"Capturar qualquer erro e retornar sucesso."},{"id":"c","texto":"Apagar o arquivo ausente e continuar sem avisar."},{"id":"d","texto":"Usar except sem tipo e ignorar a exceção."}]}'::jsonb, 'iniciante', 10, true),
  ('py-completar-apl-08', 'python', 'py-apl-08', 'completar', 'Trate arquivo ausente', 'Complete o tipo de exceção específico para um caminho que não existe.', '{"codigo":"try:\n    abrir_relatorio()\nexcept ___:\n    print(\"Confira se o arquivo está na pasta do projeto.\")","lacunas":[{"id":"excecao","rotulo":"Exceção de arquivo não encontrado"}]}'::jsonb, 'iniciante', 20, true),
  ('py-quiz-apl-09', 'python', 'py-apl-09', 'quiz', 'Confirme onde o pacote será instalado', 'O pacote não aparece ao executar o projeto. Qual comando reduz o risco de instalar com outro pip que não pertence ao Python ativo?', '{"multipla":false,"alternativas":[{"id":"a","texto":"python -m pip install nome-do-pacote"},{"id":"b","texto":"abrir pip pelo navegador"},{"id":"c","texto":"python nome-do-pacote"},{"id":"d","texto":"copiar o pacote para qualquer pasta"}]}'::jsonb, 'iniciante', 10, true),
  ('py-completar-apl-09', 'python', 'py-apl-09', 'completar', 'Registre dependências', 'Complete o comando que grava os pacotes instalados no ambiente ativo em requirements.txt.', '{"codigo":"python -m pip freeze ___ requirements.txt","lacunas":[{"id":"redirecionamento","rotulo":"Símbolo que envia a saída para o arquivo"}]}'::jsonb, 'iniciante', 20, true),
  ('py-quiz-apl-10', 'python', 'py-apl-10', 'quiz', 'Uma requisição que não espera para sempre', 'Ao consultar uma API, qual medida evita que o programa aguarde indefinidamente por uma resposta?', '{"multipla":false,"alternativas":[{"id":"a","texto":"Definir um timeout e tratar erros de conexão e status HTTP."},{"id":"b","texto":"Repetir a requisição sem limite até funcionar."},{"id":"c","texto":"Assumir que toda resposta tem status 200."},{"id":"d","texto":"Ignorar o corpo e qualquer falha de rede."}]}'::jsonb, 'iniciante', 10, true),
  ('py-completar-apl-10', 'python', 'py-apl-10', 'completar', 'Defina um limite para a chamada', 'Complete a chamada requests.get para que a conexão tenha limite de cinco segundos.', '{"codigo":"resposta = requests.get(url, ___=5)","lacunas":[{"id":"parametro","rotulo":"Parâmetro de tempo limite"}]}'::jsonb, 'iniciante', 20, true),
  ('py-quiz-pro-01', 'python', 'py-pro-01', 'quiz', 'Revise antes de registrar', 'Qual comando mostra arquivos modificados, novos arquivos e o estado do staging antes de um commit?', '{"multipla":false,"alternativas":[{"id":"a","texto":"git status"},{"id":"b","texto":"git publish"},{"id":"c","texto":"git erase"},{"id":"d","texto":"git finish"}]}'::jsonb, 'iniciante', 10, true),
  ('py-completar-pro-01', 'python', 'py-pro-01', 'completar', 'Prepare um arquivo para commit', 'Complete o comando para adicionar apenas calculos.py à área de staging.', '{"codigo":"git add ___","lacunas":[{"id":"arquivo","rotulo":"Nome do arquivo a preparar"}]}'::jsonb, 'iniciante', 20, true),
  ('py-quiz-pro-02', 'python', 'py-pro-02', 'quiz', 'Não publique credenciais', 'Antes de enviar um projeto ao GitHub, onde deve ficar uma chave privada usada localmente?', '{"multipla":false,"alternativas":[{"id":"a","texto":"Fora do repositório, em configuração local protegida; o projeto documenta apenas como configurá-la."},{"id":"b","texto":"No README para facilitar o acesso."},{"id":"c","texto":"Em um arquivo .py público."},{"id":"d","texto":"Em um commit antigo, pois depois pode ser apagada."}]}'::jsonb, 'iniciante', 10, true),
  ('py-erro-pro-02', 'python', 'py-pro-02', 'erro', 'Encontre o risco antes do push', 'O comando git status mostra .env entre os arquivos novos. O que fazer antes de criar o commit?', '{"multipla":false,"alternativas":[{"id":"a","texto":"Adicionar .env ao .gitignore e conferir que não há segredo já rastreado."},{"id":"b","texto":"Enviar o arquivo e apagar depois do push."},{"id":"c","texto":"Renomear .env para senha.txt e enviar."},{"id":"d","texto":"Publicar o segredo somente em branch separada."}]}'::jsonb, 'iniciante', 20, true),
  ('py-quiz-pro-03', 'python', 'py-pro-03', 'quiz', 'Trabalhe em uma mudança isolada', 'Qual é a principal vantagem de criar uma branch antes de experimentar uma mudança?', '{"multipla":false,"alternativas":[{"id":"a","texto":"Desenvolver e revisar a mudança separadamente antes de integrá-la."},{"id":"b","texto":"Apagar automaticamente o histórico da branch principal."},{"id":"c","texto":"Fazer o Git resolver qualquer conflito sem decisão humana."},{"id":"d","texto":"Impedir que outras pessoas vejam o repositório."}]}'::jsonb, 'iniciante', 10, true),
  ('py-completar-pro-03', 'python', 'py-pro-03', 'completar', 'Crie uma branch de trabalho', 'Complete o comando para criar e já mudar para uma branch chamada melhoria.', '{"codigo":"git switch ___ melhoria","lacunas":[{"id":"opcao","rotulo":"Opção que cria uma nova branch"}]}'::jsonb, 'iniciante', 20, true),
  ('py-quiz-pro-04', 'python', 'py-pro-04', 'quiz', 'Isole o projeto', 'Qual comando cria um ambiente virtual chamado .venv com o Python que está ativo?', '{"multipla":false,"alternativas":[{"id":"a","texto":"python -m venv .venv"},{"id":"b","texto":"pip install venv global"},{"id":"c","texto":"python --global .venv"},{"id":"d","texto":"git venv create"}]}'::jsonb, 'iniciante', 10, true),
  ('py-completar-pro-04', 'python', 'py-pro-04', 'completar', 'Ative o ambiente no macOS ou Linux', 'Complete o caminho para ativar o ambiente .venv no macOS ou Linux.', '{"codigo":"source .venv/___/activate","lacunas":[{"id":"pasta","rotulo":"Pasta de executáveis do ambiente"}]}'::jsonb, 'iniciante', 20, true),
  ('py-quiz-pro-05', 'python', 'py-pro-05', 'quiz', 'Instale o que o projeto declara', 'Uma pessoa clonou o projeto e ativou o ambiente virtual. Como instala as dependências listadas em requirements.txt?', '{"multipla":false,"alternativas":[{"id":"a","texto":"python -m pip install -r requirements.txt"},{"id":"b","texto":"python requirements.txt"},{"id":"c","texto":"git install requirements.txt"},{"id":"d","texto":"pip remove requirements.txt"}]}'::jsonb, 'iniciante', 10, true),
  ('py-completar-pro-05', 'python', 'py-pro-05', 'completar', 'Instale as dependências declaradas', 'Complete a opção para instalar os pacotes listados no arquivo.', '{"codigo":"python -m pip install ___ requirements.txt","lacunas":[{"id":"opcao","rotulo":"Opção para ler uma lista de requisitos"}]}'::jsonb, 'iniciante', 20, true),
  ('py-quiz-pro-06', 'python', 'py-pro-06', 'quiz', 'Depure com uma hipótese', 'Um cálculo produz um resultado errado. Qual sequência ajuda a encontrar a causa sem mudanças aleatórias?', '{"multipla":false,"alternativas":[{"id":"a","texto":"Reproduzir o caso, formular uma hipótese e inspecionar valores no ponto relevante."},{"id":"b","texto":"Alterar muitas linhas até a saída parecer correta."},{"id":"c","texto":"Remover o teste que detectou o problema."},{"id":"d","texto":"Adicionar except genérico para esconder o erro."}]}'::jsonb, 'iniciante', 10, true),
  ('py-completar-pro-06', 'python', 'py-pro-06', 'completar', 'Pause no ponto de investigação', 'Complete a chamada que insere um breakpoint interativo neste trecho.', '{"codigo":"def calcular_total(itens):\n    ___()\n    return sum(itens)","lacunas":[{"id":"funcao","rotulo":"Função nativa que inicia a depuração"}]}'::jsonb, 'iniciante', 20, true),
  ('py-quiz-pro-07', 'python', 'py-pro-07', 'quiz', 'Leia a causa no traceback', 'Ao investigar um traceback Python, qual parte costuma identificar primeiro o tipo e a mensagem do erro?', '{"multipla":false,"alternativas":[{"id":"a","texto":"A última linha; depois, as linhas anteriores ajudam a localizar o caminho até a causa."},{"id":"b","texto":"Sempre a primeira linha, ignorando o restante."},{"id":"c","texto":"O nome do arquivo no topo, sem ler a mensagem."},{"id":"d","texto":"A quantidade de linhas em branco."}]}'::jsonb, 'iniciante', 10, true),
  ('py-erro-pro-07', 'python', 'py-pro-07', 'erro', 'Identifique um nome não definido', 'A execução termina com NameError: name "total" is not defined. Qual hipótese inicial faz sentido?', '{"multipla":false,"alternativas":[{"id":"a","texto":"O código tentou usar total antes de definir esse nome ou escreveu o nome de forma diferente."},{"id":"b","texto":"O arquivo certamente está sem permissão de rede."},{"id":"c","texto":"O Python não aceita variáveis numéricas."},{"id":"d","texto":"A única solução é reinstalar o editor."}]}'::jsonb, 'iniciante', 20, true),
  ('py-quiz-pro-08', 'python', 'py-pro-08', 'quiz', 'Teste uma regra observável', 'Qual teste oferece evidência direta de que somar(2, 3) devolve 5?', '{"multipla":false,"alternativas":[{"id":"a","texto":"def test_somar(): assert somar(2, 3) == 5"},{"id":"b","texto":"print(somar)"},{"id":"c","texto":"assert somar == 5"},{"id":"d","texto":"def test_somar: pass"}]}'::jsonb, 'iniciante', 10, true),
  ('py-completar-pro-08', 'python', 'py-pro-08', 'completar', 'Escreva uma asserção', 'Complete a condição para verificar que dobrar(4) devolve 8.', '{"codigo":"def test_dobrar():\n    ___ dobrar(4) == 8","lacunas":[{"id":"assertiva","rotulo":"Palavra-chave que verifica uma condição"}]}'::jsonb, 'iniciante', 20, true),
  ('py-quiz-pro-09', 'python', 'py-pro-09', 'quiz', 'Formate e encontre problemas', 'Qual combinação descreve melhor o uso de Ruff neste projeto?', '{"multipla":false,"alternativas":[{"id":"a","texto":"Usar ruff format para formatar e ruff check para analisar padrões e possíveis erros."},{"id":"b","texto":"Ruff substitui testes e revisão de produto."},{"id":"c","texto":"Ruff publica o projeto no GitHub automaticamente."},{"id":"d","texto":"Ruff executa o código sem interpretador."}]}'::jsonb, 'iniciante', 10, true),
  ('py-completar-pro-09', 'python', 'py-pro-09', 'completar', 'Analise o projeto com Ruff', 'Complete o comando que verifica o diretório atual com o linter Ruff.', '{"codigo":"ruff ___ .","lacunas":[{"id":"comando","rotulo":"Subcomando que analisa o código"}]}'::jsonb, 'iniciante', 20, true),
  ('py-quiz-pro-10', 'python', 'py-pro-10', 'quiz', 'Um README que outra pessoa consegue seguir', 'Qual conjunto de informações torna a documentação inicial de um projeto mais reproduzível?', '{"multipla":false,"alternativas":[{"id":"a","texto":"Objetivo, versão de Python, instalação, comando de uso, testes e limitações conhecidas."},{"id":"b","texto":"Somente o nome do autor."},{"id":"c","texto":"Uma captura de tela sem instruções."},{"id":"d","texto":"A frase funciona na minha máquina."}]}'::jsonb, 'iniciante', 10, true),
  ('py-completar-pro-10', 'python', 'py-pro-10', 'completar', 'Documente como rodar os testes', 'Complete o comando que o README pode indicar para executar os testes com pytest.', '{"codigo":"python -m ___","lacunas":[{"id":"modulo","rotulo":"Módulo que executa a suíte pytest"}]}'::jsonb, 'iniciante', 20, true),
  ('py-projeto-despesas', 'python', 'py-apl-10', 'projeto', 'Projeto — gerenciador de despesas em JSON', 'Crie um programa de terminal para cadastrar receitas e despesas, listar lançamentos, calcular saldo e persistir os dados em JSON entre execuções.', '{"objetivo":"Praticar funções, arquivos, JSON, validação e tratamento de falhas em uma aplicação de uso pessoal.","requisitos":[{"id":"lancamento","titulo":"Cadastrar lançamentos","descricao":"Registrar tipo, descrição, valor e categoria para receitas e despesas."},{"id":"listagem","titulo":"Listar e consultar","descricao":"Exibir lançamentos de forma legível e permitir consultar informações cadastradas."},{"id":"saldo","titulo":"Calcular o saldo","descricao":"Calcular receitas menos despesas a partir dos registros, sem confiar em um total desatualizado salvo separadamente."},{"id":"persistencia","titulo":"Persistir em JSON","descricao":"Salvar os dados e recuperá-los na execução seguinte usando json e pathlib ou open com with."},{"id":"validacao","titulo":"Tratar entradas e arquivos inválidos","descricao":"Validar valor e tipo do lançamento; orientar a pessoa se o arquivo estiver ausente ou com JSON inválido."},{"id":"organizacao","titulo":"Organizar em funções","descricao":"Separar leitura, gravação, cadastro, listagem e cálculo em funções com responsabilidades claras."}],"criterios":[{"id":"fluxo","titulo":"Fluxo de ponta a ponta","descricao":"Demonstra cadastro de receita e despesa, listagem e saldo atualizado."},{"id":"persistencia","titulo":"Persistência verificável","descricao":"Fecha e abre novamente o programa e confirma que os registros continuam disponíveis."},{"id":"erros","titulo":"Falhas compreensíveis","descricao":"Demonstra como o programa reage a um valor inválido e a um arquivo malformado sem declarar sucesso incorreto."},{"id":"compreensao","titulo":"Explicação do projeto","descricao":"O resumo explica como os dados são representados e quais casos foram testados."}],"entregaveis":["Link público de repositório ou arquivo .zip de até 20 MB","Resumo de pelo menos 20 caracteres com testes e aprendizados","Autoavaliação honesta dos requisitos concluídos"],"instrucoes":"Envie um link público de GitHub, GitLab ou Bitbucket, ou um arquivo .zip de até 20 MB. Explique no resumo como verificou a persistência e o saldo; marque apenas requisitos conferidos. A equipe revisará e dará feedback.","limiteResumo":2000,"plataformas":["github.com","gitlab.com","bitbucket.org"]}'::jsonb, 'iniciante', 30, true),
  ('py-projeto-ferramentas', 'python', 'py-pro-10', 'projeto', 'Projeto — refatoração e entrega reproduzível', 'Escolha um projeto anterior da trilha, organize-o para manutenção e prepare uma entrega que outra pessoa consiga instalar, testar e executar.', '{"objetivo":"Consolidar o fluxo profissional sem exigir uma aplicação nova: melhorar um projeto conhecido e demonstrar que ele continua funcional.","requisitos":[{"id":"git","titulo":"Revisar o histórico Git","descricao":"Use um repositório com commits pequenos e mensagens que expliquem as mudanças; não inclua credenciais."},{"id":"ambiente","titulo":"Criar ambiente virtual","descricao":"Documente como criar e ativar um ambiente isolado para o projeto."},{"id":"dependencias","titulo":"Registrar dependências","descricao":"Inclua requirements.txt se o projeto usar pacotes externos e explique a instalação."},{"id":"testes","titulo":"Adicionar testes pytest","descricao":"Cubra regras importantes e ao menos um caso limite com testes automatizados."},{"id":"ruff","titulo":"Executar Ruff","descricao":"Rode Ruff format e Ruff check, corrigindo os problemas relevantes encontrados."},{"id":"readme","titulo":"Escrever README reproduzível","descricao":"Explique objetivo, pré-requisitos, instalação, execução, testes e limitações conhecidas."}],"criterios":[{"id":"execucao","titulo":"Execução reproduzível","descricao":"Outra pessoa consegue preparar o ambiente e seguir as instruções sem depender de configurações secretas do computador original."},{"id":"testes","titulo":"Testes úteis","descricao":"Os testes passam e demonstram comportamentos do programa, incluindo um limite relevante."},{"id":"qualidade","titulo":"Qualidade automatizada","descricao":"As instruções de formatação e lint estão documentadas e Ruff não aponta problemas pendentes relevantes."},{"id":"compreensao","titulo":"Mudanças explicadas","descricao":"O resumo descreve o que foi refatorado, por que e como foi verificado."}],"entregaveis":["Link público de repositório ou arquivo .zip de até 20 MB","Resumo de pelo menos 20 caracteres explicando refatoração e testes","Autoavaliação honesta dos requisitos concluídos"],"instrucoes":"Envie o repositório público ou um .zip de até 20 MB. Não inclua segredos, ambientes virtuais nem dados pessoais. Conte no resumo o que refatorou e como executou os testes; marque apenas requisitos verificados. A equipe revisará e dará feedback.","limiteResumo":2000,"plataformas":["github.com","gitlab.com","bitbucket.org"]}'::jsonb, 'iniciante', 30, true)
insert into public.atividade_gabarito (atividade_id, configuracao) values
  ('py-quiz-apl-01', '{"corretas":["a"],"explicacao":"O módulo é carregado e as definições ficam disponíveis. O bloco protegido por __name__ == \"__main__\" só roda quando o arquivo é executado como programa principal."}'::jsonb),
  ('py-completar-apl-01', '{"lacunas":{"palavra":["import"]},"explicacao":"A forma from modulo import nome importa um elemento específico definido no módulo."}'::jsonb),
  ('py-quiz-apl-02', '{"corretas":["a"],"explicacao":"math faz parte da biblioteca padrão e oferece sqrt. Consultar a documentação ajuda a entender o comportamento antes de instalar outra dependência."}'::jsonb),
  ('py-saida-apl-02', '{"aceitas":["4"],"explicacao":"math.floor arredonda para baixo em direção ao menor inteiro. Para 4.9, o resultado é 4."}'::jsonb),
  ('py-quiz-apl-03', '{"corretas":["a"],"explicacao":"timedelta representa uma duração e pode ser somada a objetos date ou datetime."}'::jsonb),
  ('py-saida-apl-03', '{"aceitas":["2025-02-01"],"explicacao":"Somar dois dias a 30 de janeiro cruza o fim do mês. O objeto date calcula a data seguinte corretamente."}'::jsonb),
  ('py-quiz-apl-04', '{"corretas":["a"],"explicacao":"pathlib permite compor caminhos com o operador /. Assim a biblioteca escolhe o separador apropriado ao sistema."}'::jsonb),
  ('py-completar-apl-04', '{"lacunas":{"operador":["/"]},"explicacao":"Path implementa o operador / para compor partes de um caminho de forma portável."}'::jsonb),
  ('py-quiz-apl-05', '{"corretas":["a"],"explicacao":"O modo a acrescenta conteúdo ao final. w cria ou substitui o arquivo, enquanto r é para leitura."}'::jsonb),
  ('py-erro-apl-05', '{"corretas":["a"],"explicacao":"Abrir em modo w trunca um arquivo existente. Use a para acrescentar sem substituir o conteúdo anterior."}'::jsonb),
  ('py-quiz-apl-06', '{"corretas":["a"],"explicacao":"json.load lê JSON de um objeto de arquivo e json.dump grava uma estrutura Python compatível nesse arquivo."}'::jsonb),
  ('py-completar-apl-06', '{"lacunas":{"funcao":["load"]},"explicacao":"json.load recebe o arquivo aberto e converte o JSON em estruturas Python como listas e dicionários."}'::jsonb),
  ('py-quiz-apl-07', '{"corretas":["a"],"explicacao":"CSV tem regras de aspas e separadores. DictReader respeita essas regras e mapeia campos pelo cabeçalho, ao contrário de split simples."}'::jsonb),
  ('py-completar-apl-07', '{"lacunas":{"leitor":["DictReader"]},"explicacao":"csv.DictReader usa a primeira linha como cabeçalho e entrega cada registro como um dicionário."}'::jsonb),
  ('py-quiz-apl-08', '{"corretas":["a"],"explicacao":"Capture a falha prevista que consegue tratar e ofereça um caminho de recuperação. Um except genérico pode esconder erros de programação."}'::jsonb),
  ('py-completar-apl-08', '{"lacunas":{"excecao":["FileNotFoundError"]},"explicacao":"FileNotFoundError indica que o caminho procurado não corresponde a um arquivo disponível."}'::jsonb),
  ('py-quiz-apl-09', '{"corretas":["a"],"explicacao":"python -m pip executa o pip associado a esse interpretador Python, reduzindo confusão entre ambientes."}'::jsonb),
  ('py-completar-apl-09', '{"lacunas":{"redirecionamento":[">"]},"explicacao":"O operador > direciona a saída de pip freeze para requirements.txt. Tenha certeza do ambiente ativo antes de registrar os pacotes."}'::jsonb),
  ('py-quiz-apl-10', '{"corretas":["a"],"explicacao":"Timeout limita o tempo de espera. Também é necessário verificar o status e validar os dados da resposta; uma chamada externa pode falhar."}'::jsonb),
  ('py-completar-apl-10', '{"lacunas":{"parametro":["timeout"]},"explicacao":"O parâmetro timeout limita quanto tempo a chamada espera por uma resposta da API."}'::jsonb),
  ('py-quiz-pro-01', '{"corretas":["a"],"explicacao":"git status mostra o estado de arquivos e do staging para você revisar o que será registrado."}'::jsonb),
  ('py-completar-pro-01', '{"lacunas":{"arquivo":["calculos.py"]},"explicacao":"git add calculos.py prepara somente esse arquivo para entrar no próximo commit."}'::jsonb),
  ('py-quiz-pro-02', '{"corretas":["a"],"explicacao":"Credenciais não devem entrar no código ou no histórico do Git. Use configuração local protegida e documente os nomes das variáveis necessárias sem seus valores."}'::jsonb),
  ('py-erro-pro-02', '{"corretas":["a"],"explicacao":"Um .env frequentemente contém segredos. Ignore-o antes do commit e confirme se já não está rastreado; apagar um segredo depois do push não o remove do histórico."}'::jsonb),
  ('py-quiz-pro-03', '{"corretas":["a"],"explicacao":"Branches isolam trabalho e facilitam revisão. Um conflito exige entender e decidir como integrar alterações concorrentes."}'::jsonb),
  ('py-completar-pro-03', '{"lacunas":{"opcao":["-c"]},"explicacao":"git switch -c melhoria cria a nova branch e muda para ela."}'::jsonb),
  ('py-quiz-pro-04', '{"corretas":["a"],"explicacao":"python -m venv .venv cria um ambiente virtual dentro do projeto, sem alterar o interpretador global."}'::jsonb),
  ('py-completar-pro-04', '{"lacunas":{"pasta":["bin"]},"explicacao":"No macOS e Linux, o script de ativação costuma estar em .venv/bin/activate. No Windows o caminho é diferente."}'::jsonb),
  ('py-quiz-pro-05', '{"corretas":["a"],"explicacao":"A opção -r instrui pip a ler os pacotes necessários de requirements.txt."}'::jsonb),
  ('py-completar-pro-05', '{"lacunas":{"opcao":["-r"]},"explicacao":"pip install -r requirements.txt instala os pacotes listados no arquivo no ambiente ativo."}'::jsonb),
  ('py-quiz-pro-06', '{"corretas":["a"],"explicacao":"Reproduzir o caso e inspecionar o estado transforma a depuração em uma investigação verificável, em vez de tentativa aleatória."}'::jsonb),
  ('py-completar-pro-06', '{"lacunas":{"funcao":["breakpoint"]},"explicacao":"breakpoint() pausa a execução e permite inspecionar valores. Remova-o ou desative-o antes de entregar o programa."}'::jsonb),
  ('py-quiz-pro-07', '{"corretas":["a"],"explicacao":"A última linha normalmente nomeia a exceção e sua mensagem. As linhas anteriores apontam a sequência de chamadas até o local relevante."}'::jsonb),
  ('py-erro-pro-07', '{"corretas":["a"],"explicacao":"NameError indica que o nome não estava definido no escopo consultado. Verifique ordem de definição e erros de digitação."}'::jsonb),
  ('py-quiz-pro-08', '{"corretas":["a"],"explicacao":"O teste chama a função com dados conhecidos e compara o retorno com o resultado esperado."}'::jsonb),
  ('py-completar-pro-08', '{"lacunas":{"assertiva":["assert"]},"explicacao":"assert verifica uma condição e faz o teste falhar quando o resultado não corresponde ao esperado."}'::jsonb),
  ('py-quiz-pro-09', '{"corretas":["a"],"explicacao":"ruff format padroniza a formatação e ruff check encontra padrões problemáticos. Testes e revisão continuam necessários."}'::jsonb),
  ('py-completar-pro-09', '{"lacunas":{"comando":["check"]},"explicacao":"ruff check . analisa os arquivos do diretório atual."}'::jsonb),
  ('py-quiz-pro-10', '{"corretas":["a"],"explicacao":"Um README útil informa como preparar o ambiente e executar o projeto, além de explicar testes e limitações."}'::jsonb),
  ('py-completar-pro-10', '{"lacunas":{"modulo":["pytest"]},"explicacao":"python -m pytest executa pytest usando o interpretador do ambiente ativo."}'::jsonb)
